      pt: ["A fachada consiste em 1.100 painéis de vidro curvos.", "O Grande Salão comporta 2.100 espectadores.", "O edifício tem 110 metros de altura e ergue-se sobre o Elba.", "Os arquitetos foram Herzog & de Meuron da Suíça.", "A Plaza a 37 metros de altura tem acesso gratuito."],
      fr: ["La façade se compose de 1 100 vitres incurvées.", "La Grande Salle peut accueillir 2 100 spectateurs.", "Le bâtiment mesure 110 mètres de haut et surplombe l'Elbe.", "Les architectes sont les Suisses Herzog & de Meuron.", "La Plaza située à 37 mètres de hauteur est accessible gratuitement."],
