      ro: ["Acordarea drepturilor de oraș în anul 1664", "A aparținut statului danez între 1640 și 1864", "Integrarea în Hamburg a avut loc abia în 1937", "Celebra piață de pește funcționează din 1703", "Populația districtului este de cca. 275.000 locuitori", "Bulevardul istoric Palmaille a fost creat în secolul XVII"],
