        "Bergedorfnak saját történelmi belváros-magja van piactérrel.",
        "A Hamburgi Csillagvizsgáló Bergedorfban egy történelmi kutatóintézet.",
        "A Sachsenwald, Schleswig-Holstein legnagyobb összefüggő erdeje, Bergedorf közelében terül el.",
