      es: ["La acería de Neunkirchen marcó la ciudad durante décadas.", "El Zoo de Neunkirchen es un destino de ocio popular en la región.", "El Stummsche Revier es una zona industrial revitalizada con un centro comercial.", "Neunkirchen se encuentra en el centro geográfico del Sarre.", "La ciudad tiene unos 47.000 habitantes."],
      pt: ["A usina siderúrgica de Neunkirchen moldou a cidade durante décadas.", "O Jardim Zoológico de Neunkirchen é um destino de lazer popular na região.", "O Stummsche Revier é uma zona industrial revitalizada com um centro comercial.", "Neunkirchen está localizada no centro geográfico do Sarre.", "A cidade tem cerca de 47.000 habitantes."],
