      es: "Homburg es una ciudad del Sarre, famosa por las cuevas del Schlossberg, las cuevas de arenisca más grandes de Europa, y como ciudad universitaria.",
      pt: "Homburg é uma cidade do Sarre, conhecida pelas grutas do Schlossberg, as maiores grutas de arenito da Europa, e como cidade universitária.",
