      es: ["Las cuevas del Schlossberg forman una red de unos 2 km de longitud.", "Las cuevas se usaron como refugio durante la Segunda Guerra Mundial.", "El Hospital Universitario del Sarre en Homburg es uno de los más grandes de Alemania.", "Homburg es una de las ciudades más grandes del Sarre con unos 40.000 habitantes.", "Los restos de la fortaleza de Karlsberg muestran la historia relevante de la ciudad."],
      pt: ["As grutas do Schlossberg compreendem uma rede de cerca de 2 km de comprimento.", "As grutas foram utilizadas como abrigo durante a Segunda Guerra Mundial.", "O Hospital Universitário do Sarre em Homburg é um dos maiores da Alemanha.", "Homburg é uma das maiores cidades do Sarre, com cerca de 40.000 habitantes.", "Os vestígios da fortaleza de Karlsberg mostram a história significativa da cidade."],
      fr: ["Les grottes du Schlossberg forment un réseau d'environ 2 km de long.", "Les grottes ont servi d'abri pendant la Seconde Guerre mondiale.", "Le CHU de Sarre à Homburg est l'un des plus grands d'Allemagne.", "Homburg est l'une des plus grandes villes de Sarre avec 40 000 habitants.", "Les vestiges de la forteresse de Karlsberg témoignent du passé de la ville."],
