      en: ["Residential seat of the Counts of Leyen in the 18th century", "Central Europe's largest menhir (Gollenstein) at 6.6 meters height", "Historic old town with listed baroque buildings", "Pilgrimage center featuring the 'Our Lady' devotional chapel", "Headquarters of the Bliesgau Biosphere Reserve administration", "Famous for the baroque Hercules fountain in the market square"],
      es: ["Residencia de los condes de la Leyen en el siglo XVIII", "Menhir más grande de Europa Central (Gollenstein) con 6,6 metros de altura", "Casco antiguo histórico con edificios barrocos protegidos", "Centro de peregrinación con la capilla milagrosa de 'Nuestra Señora'", "Sede principal de la administración de la Reserva de la Biosfera del Bliesgau", "Conocida por la barroca fuente de Hércules en la plaza del mercado"],
