      fr: ["Ville de résidence des comtes de la Leyen au XVIIIe siècle", "Plus grand menhir d'Europe centrale (Gollenstein) avec 6,6 mètres de haut", "Vieille ville historique avec des édifices baroques classés", "Centre de pèlerinage avec la chapelle miraculeuse « Notre-Dame »", "Siège principal de l'administration de la réserve de biosphère du Bliesgau", "Réputée pour sa fontaine d'Hercule baroque sur la place du marché"],
