      ro: ["Cel mai înalt munte de observație din Saarland, cu 568 de metri", "Redeschiderea turnului de observație renovat în anul 2013", "Locul unei fortificații celtice și al unei cetăți romane", "Formațiune geologică de origine vulcanică (lavă de Schaumberg)", "Proximitatea față de Abația Tholey, cea mai veche mănăstire din Germania", "Punct de lansare pentru parapantiști cu o panoramă vastă"],
